/**
 * The vault: people, notes and face fingerprints, stored only in this
 * browser's IndexedDB and encrypted with AES-GCM.
 *
 * The key is generated by the browser as non-extractable: page code can use it
 * to encrypt and decrypt, but it can never be read out, exported or sent
 * anywhere. Deleting everything removes the records and the key together.
 */
import { deleteDB, openDB, type DBSchema, type IDBPDatabase } from 'idb';
import type { Person } from './types';

const DB_NAME = 'face-whisper';
const DB_VERSION = 1;

interface EncryptedRecord {
  id: string;
  iv: Uint8Array<ArrayBuffer>;
  data: ArrayBuffer;
  v: 1;
}

interface VaultSchema extends DBSchema {
  people: { key: string; value: EncryptedRecord };
  keys: { key: string; value: CryptoKey };
}

let dbPromise: Promise<IDBPDatabase<VaultSchema>> | null = null;
let keyPromise: Promise<CryptoKey> | null = null;

function db(): Promise<IDBPDatabase<VaultSchema>> {
  dbPromise ??= openDB<VaultSchema>(DB_NAME, DB_VERSION, {
    upgrade(database) {
      database.createObjectStore('people', { keyPath: 'id' });
      database.createObjectStore('keys');
    },
  });
  return dbPromise;
}

function vaultKey(): Promise<CryptoKey> {
  keyPromise ??= (async () => {
    const database = await db();
    const existing = await database.get('keys', 'main');
    if (existing) return existing;
    const key = await crypto.subtle.generateKey({ name: 'AES-GCM', length: 256 }, false, ['encrypt', 'decrypt']);
    await database.put('keys', key, 'main');
    return key;
  })();
  keyPromise.catch(() => {
    keyPromise = null;
  });
  return keyPromise;
}

async function encrypt(person: Person): Promise<EncryptedRecord> {
  const iv = crypto.getRandomValues(new Uint8Array(new ArrayBuffer(12)));
  const plain = new TextEncoder().encode(JSON.stringify(person));
  const data = await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, await vaultKey(), plain);
  return { id: person.id, iv, data, v: 1 };
}

async function decrypt(record: EncryptedRecord): Promise<Person> {
  const plain = await crypto.subtle.decrypt({ name: 'AES-GCM', iv: record.iv }, await vaultKey(), record.data);
  return JSON.parse(new TextDecoder().decode(plain)) as Person;
}

export async function listPeople(): Promise<Person[]> {
  const records = await (await db()).getAll('people');
  const people: Person[] = [];
  for (const record of records) {
    try {
      people.push(await decrypt(record));
    } catch {
      // A record that no longer decrypts (key lost) is unusable; skip it.
    }
  }
  return people.sort((a, b) => a.name.localeCompare(b.name));
}

export async function getPerson(id: string): Promise<Person | undefined> {
  const record = await (await db()).get('people', id);
  return record ? decrypt(record) : undefined;
}

export async function savePerson(person: Person): Promise<void> {
  const record = await encrypt(person);
  await (await db()).put('people', record);
}

export async function deletePerson(id: string): Promise<void> {
  await (await db()).delete('people', id);
}

/** Removes every person and the encryption key, then the database itself. */
export async function wipeVault(): Promise<void> {
  if (dbPromise) {
    try {
      (await dbPromise).close();
    } catch {
      // already closed
    }
  }
  dbPromise = null;
  keyPromise = null;
  await deleteDB(DB_NAME);
}

/** For tests and diagnostics: the raw stored record, to prove it is ciphertext. */
export async function rawRecord(id: string): Promise<EncryptedRecord | undefined> {
  return (await db()).get('people', id);
}
